describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 1.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
      { upToGrams: 10000, costCents: 2000 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with only weightless items", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([weightlessLine], 2000)).toBe(0);
    });

    it("selects first bracket when weight is at boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g * 2 = 1000g → first bracket (upToGrams: 1000)
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 500 },
        quantity: 2,
      };
      expect(calc.computeShippingCents([line], 5000)).toBe(500);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g * 2 = 1002g → second bracket
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 501 },
        quantity: 2,
      };
      expect(calc.computeShippingCents([line], 5000)).toBe(1000);
    });

    it("selects the heaviest bracket for weight at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 5000g exactly → second bracket
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 5000 },
        quantity: 1,
      };
      expect(calc.computeShippingCents([line], 5000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 3000);
      // 6000g * 2 = 12000g → overflow
      expect(calc.computeShippingCents([heavyLine], 10000)).toBe(3000);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g → overflow, no overflowCostCents → last bracket cost = 2000
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 11000 },
        quantity: 1,
      };
      expect(calc.computeShippingCents([line], 5000)).toBe(2000);
    });

    it("sorts brackets by upToGrams regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1000 },
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 10000, costCents: 2000 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 800 },
        quantity: 1,
      };
      expect(calc.computeShippingCents([line], 5000)).toBe(500);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const widgetA: Product = { id: "a", name: "Widget A", unitPriceCents: 1000 };
const widgetB: Product = { id: "b", name: "Widget B", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart – line management", () => {
  it("add merges quantity for the same product", () => {
    const cart = new Cart();
    cart.add(widgetA, 2);
    cart.add(widgetA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add keeps separate lines for different products", () => {
    const cart = new Cart();
    cart.add(widgetA, 1);
    cart.add(widgetB, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("add rejects zero quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widgetA, 0)).toThrow(RangeError);
  });

  it("add rejects negative quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widgetA, -1)).toThrow(RangeError);
  });

  it("add rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widgetA, 1.5)).toThrow(RangeError);
  });

  it("add rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(widgetA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    const cart = new Cart();
    cart.add(widgetA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(widgetA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widgetA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow("not in the cart");
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(widgetA, 2);
    cart.add(widgetB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widgetA, 2);
    const snap = cart.snapshot();
    // Mutating snapshot should not affect cart
    (snap as any)[0].quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart – pricing pipeline", () => {
  it("empty cart yields all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal is sum of unitPrice * quantity", () => {
    const cart = new Cart();
    cart.add(widgetA, 2); // 2000
    cart.add(widgetB, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("discount is applied to subtotal and clamped", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widgetA, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("discount is clamped to subtotal (never negative total)", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widgetA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("negative discount is clamped to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widgetA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax, region: "US-CA" });
    cart.add(widgetA, 1); // subtotal 1000, discount 200, discounted 800
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(widgetA, 1); // subtotal 1000, discounted 700
    const totals = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 100,
    };
    const tax: TaxCalculator = {
      computeTaxCents: () => 50,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 200,
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(widgetA, 1); // subtotal 1000, discount 100, discounted 900
    const totals = cart.totals();
    expect(totals.totalCents).toBe(900 + 50 + 200);
  });

  it("uses default region 'US' when not specified", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widgetA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("negative tax is clamped to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widgetA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping is clamped to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(widgetA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

