        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("w1");
        expect(ie.requested).toBe(2);
        expect(ie.available).toBe(0);
        expect(ie.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(widget, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("w1");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(3);
      }
    });

    it("checks each line and throws on first failure", async () => {
      const cart = new Cart();
      cart.add(widget, 1);
      cart.add(gadget, 1);
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true, availableQuantity: 10 })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("g1");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(widget, 1); // subtotal 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(widget, 1); // subtotal 1000, discount 200, discounted 800
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // tax = 10% of 800 = 80
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.discountCents).toBe(200);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(widget, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("service unavailable")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "service unavailable",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh, discount, async tax, and shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(widget, 2); // original 1000 each

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      // discount = 10% of 3000 = 300
      expect(result.totals.discountCents).toBe(300);
      // discounted = 2700, tax = 8% of 2700 = 216
      expect(result.totals.taxCents).toBe(216);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 2700 + 216 + 500 = 3416
      expect(result.totals.totalCents).toBe(3416);
    });

    it("returns updated lines in result", async () => {
      const cart = new Cart();
      cart.add(widget, 3);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(999),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.unitPriceCents).toBe(999);
      expect(result.lines[0].quantity).toBe(3);
    });
  });
});

